import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { ChromeBridge } from "./bridge.ts";
import { MIN_EXTENSION_VERSION } from "./protocol.ts";
import { logger } from "../logo.ts";

/**
 * 用 pi-chrome 抓 Twitter（X）时间线。
 *
 * 抓取的是**用户真实 Chrome profile 里的已登录会话**（Chrome 伴侣扩展干的活），
 * 产出 `runs/<date>/twitter_raw.txt`，格式与原先 dokobot 的产物同构——
 * 下游 `parseTwitterRaw` 按同一套格式还原。
 */

/** 一条推文。字段与页面上的可见信息一一对应，缺失就是 null。 */
export interface Tweet {
  /** 显示名。 */
  name: string | null;
  /** @handle（含 @）。 */
  handle: string | null;
  /** 发布时间（UTC ISO）。 */
  time: string | null;
  /** 正文。 */
  text: string | null;
  /** 正文里的外链（X 上是 `https://t.co/…`）。正文里没有链接就是 null。 */
  links: string[] | null;
  /** 推文直链。 */
  url: string | null;
  replies: number | null;
  reposts: number | null;
  likes: number | null;
  views: number | null;
}

